          <label>検証DBに追加する列のテーブル<select value={forkColumnEntity} onChange={event=>setForkColumnEntity(event.target.value)}>{db.fork.entities.map(item=><option key={item.key} value={item.key}>{item.table.name}</option>)}</select></label>
